**What this code covers**

- Toy event-sourced aggregate with snapshot + projection.
- Event definitions (immutable, versioned)
- Event Store (append-only, optimistic concurrency)
- Rebuild state from event store (using snapshot if available)
- Pure apply: how each event changes state
- Command handlers: validate, emit events (do NOT mutate state directly)
- Projection: rebuild a read-optimized view from the event log
- Rebuild from event log (will use snapshot if available)

**Defines:** `Created`, `Credited`, `Debited`, `AddressChanged`, `EventStore`, `SnapshotStore`, `Customer`, `CustomerBalanceProjection`

```python
"""
Toy event-sourced aggregate with snapshot + projection.
Models a Customer billing account: Created, Credited, Debited, AddressChanged.
"""
from dataclasses import dataclass, field
from typing import List, Dict, Callable

# --- Event definitions (immutable, versioned) ---
@dataclass(frozen=True)
class Created:    aggregate_id: str; name: str; address: str
@dataclass(frozen=True)
class Credited:   amount: int; reason: str
@dataclass(frozen=True)
class Debited:    amount: int; reason: str
@dataclass(frozen=True)
class AddressChanged: new_address: str

# --- Event Store (append-only, optimistic concurrency) ---
class EventStore:
    def __init__(self):
        self.streams: Dict[str, list] = {}   # aggregate_id -> [events]
    def append(self, agg_id, events, expected_version):
        stream = self.streams.setdefault(agg_id, [])
        if len(stream) != expected_version:
            raise RuntimeError(f"concurrency: expected v{expected_version}, "
                                f"got v{len(stream)}")
        stream.extend(events)
        return len(stream)
    def load(self, agg_id, since=0):
        return self.streams.get(agg_id, [])[since:]

# --- Snapshot Store ---
class SnapshotStore:
    def __init__(self): self.snaps: Dict[str, tuple] = {}   # id -> (version, state)
    def save(self, agg_id, version, state): self.snaps[agg_id] = (version, state)
    def load(self, agg_id): return self.snaps.get(agg_id)

# --- Aggregate: Customer account ---
class Customer:
    def __init__(self, id):
        self.id = id; self.version = 0
        self.name = ""; self.address = ""; self.balance = 0
        self._pending: list = []

    # Rebuild state from event store (using snapshot if available)
    def load_from(self, store: EventStore, snaps: SnapshotStore):
        snap = snaps.load(self.id)
        start = 0
        if snap:
            self.version, (self.name, self.address, self.balance) = snap
            start = self.version
        for e in store.load(self.id, since=start):
            self._apply(e); self.version += 1
        return self

    # Pure apply: how each event changes state
    def _apply(self, e):
        if isinstance(e, Created):         self.name, self.address = e.name, e.address
        elif isinstance(e, Credited):      self.balance += e.amount
        elif isinstance(e, Debited):       self.balance -= e.amount
        elif isinstance(e, AddressChanged): self.address = e.new_address

    # Command handlers: validate, emit events (do NOT mutate state directly)
    def create(self, name, address):
        if self.version != 0: raise RuntimeError("already created")
        self._emit(Created(self.id, name, address))

    def credit(self, amount, reason):
        if amount <= 0: raise ValueError("amount must be positive")
        self._emit(Credited(amount, reason))

    def debit(self, amount, reason):
        if self.balance - amount < 0: raise ValueError("insufficient funds")
        self._emit(Debited(amount, reason))

    def change_address(self, new_address):
        if not new_address: raise ValueError("address required")
        self._emit(AddressChanged(new_address))

    def _emit(self, e): self._pending.append(e); self._apply(e); self.version += 1

    def save_to(self, store: EventStore, snaps: SnapshotStore, snap_every=3):
        expected = self.version - len(self._pending)
        store.append(self.id, self._pending, expected)
        if self.version % snap_every == 0:
            snaps.save(self.id, self.version,
                       (self.name, self.address, self.balance))
        self._pending.clear()

# --- Projection: rebuild a read-optimized view from the event log ---
class CustomerBalanceProjection:
    def __init__(self): self.view: Dict[str, int] = {}
    def handle(self, agg_id, event):
        b = self.view.setdefault(agg_id, 0)
        if isinstance(event, Credited): b += event.amount; self.view[agg_id] = b
        elif isinstance(event, Debited): b -= event.amount; self.view[agg_id] = b

# --- Demo ---
store = EventStore(); snaps = SnapshotStore()
c = Customer("cust_42"); c.create("Alice", "LA")
c.credit(100, "signup bonus"); c.debit(30, "first order")
c.change_address("SF"); c.save_to(store, snaps)

# Rebuild from event log (will use snapshot if available)
c2 = Customer("cust_42").load_from(store, snaps)
print(f"name={c2.name} addr={c2.address} balance={c2.balance} v={c2.version}")

# Build projection by replaying the event log
proj = CustomerBalanceProjection()
for e in store.load("cust_42"):
    proj.handle("cust_42", e)
print(f"projection balance for cust_42: {proj.view['cust_42']}")
```
